"""API Spec."""
from typing import Any, Dict

from apispec.ext.marshmallow import MarshmallowPlugin
from apispec_webframeworks.flask import FlaskPlugin
from flasgger import APISpec, Swagger
from flask import Flask

spec = APISpec(
    title="Holocron",
    version="1.0.0",
    openapi_version="3.0.2",
    plugins=[
        FlaskPlugin(),
        MarshmallowPlugin(),
    ],
)


def override_collector_target_spec(
    template: Dict[str, Any], key: str, schema: str
) -> Dict[str, Any]:
    """Override autogenerated collector target references with the given schema."""
    template["components"]["schemas"]["ExistingTeam"]["properties"][key]["items"][
        "$ref"
    ] = f"#/components/schemas/{schema}"
    return template


def generate_spec(app: Flask):
    """Generate and serve the API spec."""
    with app.test_request_context():
        for rule in app.url_map.iter_rules():
            spec.path(view=app.view_functions[rule.endpoint])

    template = spec.to_flasgger(app)
    template = override_collector_target_spec(template, "pipelines", "Pipeline")
    template = override_collector_target_spec(template, "repositories", "Repository")
    template = override_collector_target_spec(template, "ticketBoards", "TicketBoard")

    del template["components"]["schemas"]["CollectorTarget"]

    swagger_config = Swagger.DEFAULT_CONFIG
    swagger_config["specs_route"] = "/api/v1"
    Swagger(
        app,
        template=template,
        config=swagger_config,
    )
